<script setup>
import { computed, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { jointStore as store, PEOPLE, CHECKABLE_SPACE_TYPES, clone, localDate, displayTime } from '../../data/equipmentInspectionMock.js'
import RulePreview from './RulePreview.vue'
import ExpansionPreview from './ExpansionPreview.vue'
const filters=ref({text:'',status:''}), applied=ref(clone(filters.value)), page=ref(1)
const rows=computed(()=>store.state.plans.filter(row=>(!applied.value.text || `${row.code}${row.name}`.includes(applied.value.text)) && (!applied.value.status || row.status===applied.value.status)))
function query(){applied.value=clone(filters.value);applied.value.text=applied.value.text.trim();page.value=1}
function reset(){filters.value={text:'',status:''};query()}
const show=ref(false), step=ref(0), draft=ref({}), error=ref(''), rangeSearch=ref(''), rangeSpace=ref(''), detailId=ref('')
const rule=computed(()=>store.byId(store.state.rules,draft.value.ruleId))
const enabledRules=computed(()=>store.state.rules.filter(rule=>rule.status==='已启用'))
const expansion=computed(()=>store.preview(draft.value.ruleId,draft.value.rootIds || [],draft.value.applicableStates || []))
const signature=computed(()=>store.signature(draft.value.ruleId,draft.value.rootIds || [],draft.value.applicableStates || []))
const confirmed=computed({get:()=>Boolean(draft.value.confirmation && draft.value.confirmation===signature.value),set:value=>draft.value.confirmation=value?signature.value:''})
const issues=computed(()=>store.planIssues(draft.value))
const candidates=computed(()=>[...store.state.spaces.filter(row=>CHECKABLE_SPACE_TYPES.includes(row.type)),...store.state.assets].filter(row=>store.typeOf(row)===rule.value?.rootType && (!rangeSearch.value || `${row.code}${row.name}${row.model || ''}`.includes(rangeSearch.value)) && (!rangeSpace.value || store.ancestors(store.state.spaces,store.typeOf(row)==='空间'?row.id:row.spaceId).some(parent=>parent.id===rangeSpace.value))))
const detail=computed(()=>store.byId(store.state.plans,detailId.value))
function open(row){draft.value=row?clone(row):{id:'',code:'',name:'',ruleId:'',rootIds:[],cycle:'每日',weekDays:[1],monthDay:1,intervalDays:1,slots:[{start:'08:00',end:'09:00'}],startDate:localDate(),endDate:'',personId:'person-01',applicableStates:[],notes:'',confirmation:''};draft.value.confirmation='';step.value=0;error.value='';rangeSearch.value='';rangeSpace.value='';show.value=true}
function changeRule(){draft.value.rootIds=[];draft.value.confirmation=''}
function selectRoot(id,value){draft.value.rootIds=value?[...new Set([...draft.value.rootIds,id])]:draft.value.rootIds.filter(rootId=>rootId!==id);draft.value.confirmation=''}
function selectApplicable(){draft.value.rootIds=[...new Set([...draft.value.rootIds,...candidates.value.filter(row=>!store.rootIssue(rule.value,row,draft.value.applicableStates)).map(row=>row.id)])];draft.value.confirmation=''}
function next(){error.value='';if(step.value===0 && !rule.value){error.value='请先选择一次巡检规则';return}if(step.value===1 && !draft.value.rootIds.length){error.value='请选择至少一个实际对象';return}if(step.value===2 && !confirmed.value){error.value='请处理缺失关系 / 不适用对象，并核对展开结果';return}step.value++}
function save(enable){try{const saved=store.savePlan(draft.value,enable);show.value=false;ElMessage.success(`${saved.name} 已${enable?'启用':'保存为草稿'}，配置仅作用于未来任务`)}catch(e){error.value=e.message}}
function toggle(row){try{store.togglePlan(row.id);ElMessage.success(row.status==='已停用'?'计划已停用，历史任务与记录保留':'计划已通过核验并启用')}catch(e){ElMessage.error(e.message)}}
const generation=ref(false), generationPlanId=ref(''), generationDate=ref(localDate()), generationSlot=ref(''), generationError=ref(''), generatedId=ref('')
const generationPlan=computed(()=>store.byId(store.state.plans,generationPlanId.value))
function openGeneration(row){generationPlanId.value=row.id;generationDate.value=localDate();generationSlot.value=row.slots?.[0]?.start || '';generationError.value='';generatedId.value='';generation.value=true}
function generate(){try{const task=store.generateTask(generationPlanId.value,generationDate.value,generationSlot.value);generatedId.value=task.id;generationError.value='';ElMessage.success(`已模拟生成 ${task.code}，含${task.points.length}个检查点`)}catch(e){generationError.value=e.message}}
</script>
<template>
  <main class="inspection-page"><header class="heading"><div><div class="eyebrow">巡检管理 / 范围与责任</div><h1>巡检计划与路线</h1><p class="subtitle">一次选规则，批量选实际范围，展开核对后设置周期与主执行人。</p></div><el-button type="primary" @click="open()">创建巡检计划</el-button></header><p class="demo-note">本地 Mock 演示 · 一个计划的一个时段形成一张任务，可含多个检查点。一期按点位组织执行，不建立独立路线库或路径算法；任务由演示按钮生成。</p><el-alert v-if="store.notice.persistence" :title="store.notice.persistence" type="warning" :closable="false" />
    <section class="panel"><el-form class="filters" @submit.prevent="query"><el-input v-model="filters.text" aria-label="计划查询" placeholder="计划名称 / 编号" clearable /><el-select v-model="filters.status" aria-label="计划状态" placeholder="全部计划状态" clearable><el-option v-for="status in ['草稿','已启用','已停用']" :key="status" :value="status" /></el-select><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <el-table :data="rows.slice((page-1)*10,page*10)" stripe empty-text="没有符合条件的计划"><el-table-column label="计划" min-width="230"><template #default="{row}"><el-button link type="primary" class="title-button" @click="detailId=row.id">{{ row.name }}</el-button><div class="muted">{{ row.code }} · 配置V{{ row.version }}</div></template></el-table-column><el-table-column label="一次绑定的规则" min-width="180"><template #default="{row}">{{ store.byId(store.state.rules,row.ruleId)?.name || '未选择' }}<div class="muted">V{{ store.byId(store.state.rules,row.ruleId)?.version || '—' }} · {{ row.rootIds.length }} 个根对象 / {{ row.expansion?.points.length || 0 }} 个点</div></template></el-table-column><el-table-column label="周期 / 时段" min-width="150"><template #default="{row}">{{ row.cycle }}<div class="muted" v-for="slot in row.slots" :key="slot.start">{{ slot.start }} — {{ slot.end }}</div></template></el-table-column><el-table-column label="执行人 / 状态" min-width="155"><template #default="{row}">{{ PEOPLE.find(person=>person.id===row.personId)?.name || '未配置' }}<div><el-tag :type="row.status==='已启用'?'success':'info'">{{ row.status }}</el-tag></div></template></el-table-column><el-table-column label="操作" width="225" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link @click="toggle(row)">{{ row.status==='已启用'?'停用':'启用' }}</el-button><el-button link type="primary" :disabled="row.status!=='已启用'" @click="openGeneration(row)">模拟生成</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="rows.length" :page-size="10" layout="total, prev, pager, next" class="pagination" /></section>
    <el-dialog v-model="show" :title="draft.id?'编辑计划 · 重新核对未来任务配置':'创建巡检计划'" width="min(1120px,94vw)" class="ez-dialog inspection-editor" align-center append-to-body destroy-on-close>
      <el-steps :active="step" finish-status="success" simple><el-step title="选择规则" /><el-step title="批量选范围" /><el-step title="展开核对" /><el-step title="周期与人员" /></el-steps>
      <div class="step-content"><template v-if="step===0"><el-form label-position="top"><el-form-item label="选择一次完整巡检规则" required><el-select v-model="draft.ruleId" filterable placeholder="选择已启用的规则版本" style="width:100%" @change="changeRule"><el-option v-for="row in enabledRules" :key="row.id" :value="row.id" :label="`${row.name} · V${row.version} · ${row.rootType}`" /></el-select></el-form-item></el-form><RulePreview v-if="rule" :rule="rule" /><el-empty v-else description="先选规则，再选择实际锅炉、房间、公共区域或系统" /></template>
        <template v-if="step===1"><h2>{{ rule?.name }} · 批量选择实际{{ rule?.rootType }}对象</h2><p class="caption">规则只选一次。对象的分类、位置与关系来自设备管理；不适用对象会在展开时明确阻断。</p><div class="filters"><el-input v-model="rangeSearch" aria-label="范围对象查询" placeholder="查找名称 / 编号 / 型号" clearable /><el-select v-model="rangeSpace" aria-label="范围位置筛选" placeholder="按院区 / 楼栋 / 楼层筛选" clearable filterable><el-option v-for="row in store.state.spaces" :key="row.id" :value="row.id" :label="store.spacePath(row.id)" /></el-select><el-button @click="selectApplicable">批量选择匹配对象</el-button><el-button @click="draft.rootIds=[];draft.confirmation=''">清空已选</el-button></div><p class="caption">已选 {{ draft.rootIds.length }} 个：{{ draft.rootIds.map(id=>store.object(id)?.name).join('、') || '未选择' }}</p><el-table :data="candidates" max-height="440" empty-text="没有此类型的对象，请检查规则类型或筛选条件"><el-table-column label="选择" width="65"><template #default="{row}"><el-checkbox :model-value="draft.rootIds.includes(row.id)" :aria-label="`选择${row.name}`" @change="value=>selectRoot(row.id,value)" /></template></el-table-column><el-table-column label="实际对象" min-width="170"><template #default="{row}">{{ row.name }}<div class="muted">{{ row.code }}</div></template></el-table-column><el-table-column label="安装 / 所在位置" min-width="230"><template #default="{row}">{{ store.spacePath(store.typeOf(row)==='空间'?row.id:row.spaceId) }}</template></el-table-column><el-table-column label="适配检查" min-width="220"><template #default="{row}"><span :class="store.rootIssue(rule,row,draft.applicableStates)?'warning-text':'muted'">{{ store.rootIssue(rule,row,draft.applicableStates) || '类型与适用条件匹配，待展开核对关系' }}</span></template></el-table-column></el-table></template>
        <template v-if="step===2"><h2>确认实际检查对象和项目</h2><p class="caption">当前规则：{{ rule?.name }} V{{ rule?.version }}。点位引用已有空间，不另建机房档案。</p><ExpansionPreview :expansion="expansion" /><div class="section"><el-checkbox v-model="confirmed" :disabled="Boolean(expansion.issues.length)">已核对规则版本、实际对象、检查内容和点位范围</el-checkbox><p class="caption">任何对象资料、规则或范围变化都会要求重新核对；已生成任务与历史记录不变。</p></div></template>
        <template v-if="step===3"><el-form label-position="top" class="form-grid"><el-form-item label="计划名称" required><el-input v-model="draft.name" maxlength="80" /></el-form-item><el-form-item label="周期方式" required><el-select v-model="draft.cycle"><el-option v-for="cycle in ['每日','每周','每月','固定间隔']" :key="cycle" :value="cycle" /></el-select></el-form-item><el-form-item v-if="draft.cycle==='每周'" label="执行星期" required><el-checkbox-group v-model="draft.weekDays"><el-checkbox v-for="(name,index) in ['一','二','三','四','五','六','日']" :key="name" :value="index+1">周{{ name }}</el-checkbox></el-checkbox-group></el-form-item><el-form-item v-if="draft.cycle==='每月'" label="每月执行日（1—28日）" required><el-input-number v-model="draft.monthDay" :min="1" :max="28" /></el-form-item><el-form-item v-if="draft.cycle==='固定间隔'" label="间隔天数（从有效开始日期计算）" required><el-input-number v-model="draft.intervalDays" :min="1" :max="365" /></el-form-item><el-form-item label="有效开始日期" required><el-date-picker v-model="draft.startDate" value-format="YYYY-MM-DD" type="date" /></el-form-item><el-form-item label="有效结束日期（可选）"><el-date-picker v-model="draft.endDate" value-format="YYYY-MM-DD" type="date" /></el-form-item><el-form-item label="主执行人" required><el-select v-model="draft.personId"><el-option v-for="person in PEOPLE" :key="person.id" :value="person.id" :label="person.name" /></el-select></el-form-item><el-form-item label="计划适用设备运行状态（可选）"><el-select v-model="draft.applicableStates" multiple clearable @change="draft.confirmation=''"><el-option v-for="status in ['运行','备用','停用']" :key="status" :value="status" /></el-select><p class="caption">改变工况后需返回展开步骤重新核对。</p></el-form-item><el-form-item label="计划说明" class="wide"><el-input v-model="draft.notes" type="textarea" :rows="2" maxlength="500" /></el-form-item></el-form><div class="between section"><h2>执行时段 / 班次</h2><el-button @click="draft.slots.push({start:'14:00',end:'15:00'})">增加时段</el-button></div><div v-for="(slot,index) in draft.slots" :key="index" class="slot-row"><el-time-picker v-model="slot.start" :aria-label="`时段${index+1}开始`" format="HH:mm" value-format="HH:mm" placeholder="开始时间" /><el-time-picker v-model="slot.end" :aria-label="`时段${index+1}截止`" format="HH:mm" value-format="HH:mm" placeholder="截止时间" /><el-button type="danger" plain @click="draft.slots.splice(index,1)">移除此时段</el-button></div><p class="caption">每个时段有明确开始和截止；仅人工点击模拟生成，不存在真实后台调度。</p><div v-if="issues.length" class="error-box" role="alert"><strong>启用前还需完成：</strong><ul><li v-for="issue in issues" :key="issue">{{ issue }}</li></ul></div><p v-else class="demo-note">规则版本与实际范围已核对，可以启用。配置变更只作用于未来任务。</p></template>
      </div><p v-if="error" class="error-box" role="alert">{{ error }}</p><template #footer><p v-if="draft.status==='已启用'" class="footer-note">保存为草稿会暂停后续模拟生成；已有任务与记录保留。</p><div class="actions"><el-button @click="show=false">取消</el-button><el-button @click="save(false)">保存草稿</el-button><el-button v-if="step>0" @click="step--;error=''">上一步</el-button><el-button v-if="step<3" type="primary" @click="next">下一步</el-button><el-button v-else type="primary" :disabled="Boolean(issues.length)" @click="save(true)">{{ draft.status==='已启用'?'确认更新并保持启用':'核对并启用计划' }}</el-button></div></template>
    </el-dialog>
    <el-drawer :model-value="Boolean(detail)" title="计划详情与范围快照" size="min(900px,94vw)" append-to-body @close="detailId=''"><template v-if="detail"><h2>{{ detail.name }} · 配置 V{{ detail.version }}</h2><dl class="detail-list"><dt>规则版本</dt><dd>{{ detail.ruleSnapshot?.name || store.byId(store.state.rules,detail.ruleId)?.name || '未确认' }} V{{ detail.ruleSnapshot?.version || '—' }}</dd><dt>周期 / 适用日期</dt><dd>{{ detail.cycle }} · {{ detail.startDate || '未填' }} 至 {{ detail.endDate || '不限' }}<span v-if="detail.cycle==='每周'"> · 星期{{ detail.weekDays.join('、') }}</span><span v-if="detail.cycle==='每月'"> · 每月{{ detail.monthDay }}日</span><span v-if="detail.cycle==='固定间隔'"> · 每{{ detail.intervalDays }}天</span></dd><dt>执行时段</dt><dd>{{ detail.slots.map(slot=>`${slot.start}—${slot.end}`).join('、') }}</dd><dt>主执行人</dt><dd>{{ PEOPLE.find(person=>person.id===detail.personId)?.name || '未配置' }}</dd><dt>范围确认时间</dt><dd>{{ displayTime(detail.confirmedAt) }}</dd><dt>状态 / 说明</dt><dd>{{ detail.status }} · {{ detail.notes || '—' }}</dd></dl><el-alert v-if="store.planIssues(detail).length" :title="store.planIssues(detail).join('；')" type="warning" :closable="false" /><ExpansionPreview v-if="detail.expansion" :expansion="detail.expansion" /><p v-else class="caption">尚无已确认范围，请编辑并完成展开核对。</p><p class="demo-note">历史任务保留生成时的计划版本、规则版本、实际对象和参考条件。</p></template></el-drawer>
    <el-dialog v-model="generation" title="模拟某时段生成一张任务" class="ez-dialog inspection-editor" width="min(650px,94vw)" align-center append-to-body destroy-on-close><template v-if="generationPlan"><p class="demo-note">人工点击的本地演示；同一计划、日期、时段只能生成一次。不能补造过往日期任务。</p><h2 class="section">{{ generationPlan.name }}</h2><el-form label-position="top" class="form-grid"><el-form-item label="模拟计划日期" required><el-date-picker v-model="generationDate" type="date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="执行时段" required><el-select v-model="generationSlot"><el-option v-for="slot in generationPlan.slots" :key="slot.start" :value="slot.start" :label="`${slot.start}—${slot.end}`" /></el-select></el-form-item></el-form><p v-if="generationError" class="error-box" role="alert">{{ generationError }}</p><p v-if="generatedId" class="demo-note">已生成 {{ store.byId(store.state.tasks,generatedId)?.code }}。<router-link :to="{path:'/inspection/tasks',query:{task:generatedId}}">查看任务及检查点</router-link></p></template><template #footer><el-button @click="generation=false">关闭</el-button><el-button type="primary" @click="generate">模拟生成任务</el-button></template></el-dialog>
  </main>
</template>
<style scoped src="./inspection.css"></style>
